    "lec_r4": "4. Audio & Video: Clear audio and visual quality, coherent content, verifiable actual teaching.",
    "lec_r5": "5. Deadline: Submit before 22:00 daily to the official audit channel with lecture takeaways.",
    "lec_r6": "6. Compliance: Use verified decks only. Never guarantee returns or misstate financial credentials.",
    "lec_r7": "7. Record Keeping: No reused old videos; multi-community lectures must be declared for billing.",
    "lec_r8": "8. Privacy: Obtain participant consent before publicly showing attendees faces or identities.",
